<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use App\Services\PerformanceLog;
class PerformanceLogsController extends Controller {
 private function admin(){abort_unless(auth()->check()&&auth()->user()->user_type==='admin'&&!auth()->user()->banned,403);}
 public function index(Request $r){ $this->admin();$all=PerformanceLog::recent();$filter=$r->validate(['q'=>'nullable|string|max:120','area'=>'nullable|in:public,admin','status'=>'nullable|in:error,slow']);$rows=array_values(array_filter($all,function($row)use($filter){$q=mb_strtolower(trim($filter['q']??''));$hay=mb_strtolower(\App\Services\PerformanceInsights::label($row).' '.($row['route']??'').' '.($row['pattern']??'').' '.($row['product']??'').' '.($row['request_id']??'').' '.($row['status']??''));if($q!==''&&mb_strpos($hay,$q)===false)return false;$admin=strpos($row['pattern']??'','admin')===0;if(($filter['area']??'')==='admin'&&!$admin)return false;if(($filter['area']??'')==='public'&&$admin)return false;if(($filter['status']??'')==='error'&&$row['status']<400)return false;if(($filter['status']??'')==='slow'&&$row['duration_ms']<1000)return false;return true;}));$matched=count($rows);$loaded=count($all);$page=max(1,min(8,(int)$r->input('page',1)));$visibleRows=new \Illuminate\Pagination\LengthAwarePaginator(array_slice($rows,($page-1)*25,25),count($rows),25,$page,['path'=>$r->url(),'query'=>$r->except('page')]);$settings=PerformanceLog::settings();$health=PerformanceLog::health();$runtime=['queue'=>config('queue.default'),'cache'=>config('cache.default'),'config_cached'=>app()->configurationIsCached(),'routes_cached'=>app()->routesAreCached(),'debug'=>(bool)config('app.debug'),'php'=>PHP_VERSION,'opcache_enabled'=>(bool)ini_get('opcache.enable')];return response()->view('backend.platform.performance_logs',compact('rows','settings','health','runtime','matched','loaded','visibleRows'))->header('Cache-Control','private, no-store'); }
 public function settings(Request $r){$this->admin();$d=$r->validate(['threshold'=>'required|integer|min:100|max:10000']);try{PerformanceLog::configure($r->boolean('enabled'),$d['threshold']);}catch(\Throwable $e){return redirect()->route('admin.performance-logs')->withErrors(['settings'=>'Settings save হয়নি। Performance log folder-এর PHP write permission ও hosting storage quota পরীক্ষা করুন।']);}return redirect()->route('admin.performance-logs')->with('success','Performance logging saved: '.$d['threshold'].' ms.');}
}
